		// Token: 0x06001888 RID: 6280 RVA: 0x000A70E0 File Offset: 0x000A52E0
		private void AssignNameToShip(Ship ship)
		{
			float num = 0f;
			ShipNameCampaignBehavior.NameTrait nameFlags = ShipNameCampaignBehavior.GetNameFlags(ship);
			List<int> list = new List<int>();
			for (int i = 0; i < this._fullNames.Count; i++)
			{
				if (Extensions.HasAllFlags<ShipNameCampaignBehavior.NameTrait>(this._fullNames[i].Item2, nameFlags))
				{
					list.Add(i);
					num += this._fullNames[i].Item3;
				}
			}
			if (list.Count > 0)
			{
				TextObject textObject = this.GetRandomFullName(list, num).CopyTextObject();
				list.Clear();
				for (int j = 0; j < this._firstNames.Count; j++)
				{
					if (Extensions.HasAllFlags<ShipNameCampaignBehavior.NameTrait>(this._firstNames[j].Item2, nameFlags))
					{
						list.Add(j);
					}
				}
				if (list.Count > 0)
				{
					TextObject textObject2 = this._firstNames[Extensions.GetRandomElement<int>(list)].Item1.CopyTextObject();
					textObject.SetTextVariable("NAME", textObject2);
					ship.SetName(textObject);
				}
			}
		}

		// Token: 0x06001889 RID: 6281 RVA: 0x000A71E4 File Offset: 0x000A53E4
		private static ShipNameCampaignBehavior.NameTrait GetNameFlags(Ship ship)
		{
			ShipNameCampaignBehavior.NameTrait nameTrait = ShipNameCampaignBehavior.NameTrait.None;
			if (ship.ShipHull.IsTradeShip)
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Trade;
			}
			else if (ship.ShipHull.Type == null)
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Light;
			}
			else if (ship.ShipHull.Type == 1)
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Medium;
			}
			else if (ship.ShipHull.Type == 2)
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Heavy;
			}
			CultureObject culture = ship.Owner.Culture;
			if (culture.StringId == "aserai")
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Aserai;
			}
			else if (culture.StringId == "khuzait")
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Khuzait;
			}
			else if (culture.StringId == "vlandia")
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Vlandia;
			}
			else if (culture.StringId == "sturgia")
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Sturgia;
			}
			else if (culture.StringId == "battania")
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Battania;
			}
			else if (culture.StringId == "empire")
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Empire;
			}
			else if (culture.StringId == "nord")
			{
				nameTrait |= ShipNameCampaignBehavior.NameTrait.Nord;
			}
			return nameTrait;
		}

